mapper.select:
SELECT A.TASK_ID as taskId, A.SEQ_NO, B.TASK_NAME as taskName, D.BATCH_SEQ_NO as taskGroupId, C.BATCH_NAME as taskGroupName, D.PRD_GROUP_SEQ_NO as prdGroupId, E.GROUP_NAME as prdGroupName, DATE_FORMAT(D.START_DATE, '%Y-%m-%d') as businessStartDate, DATE_FORMAT(D.END_DATE, '%Y-%m-%d') as businessEndDate, DATE_FORMAT(A.EXECUTE_DATE, '%Y-%m-%d') as batchDate, DATE_FORMAT(A.CREATE_TIME, '%Y-%m-%d %H:%i:%s:%f3') as batchStartTime, (extract(day from a.update_time-a.create_time) * 86400+ extract(hour from a.update_time-a.create_time) * 3600 + extract(minute from a.update_time-a.create_time) * 60+ extract(second from a.update_time-a.create_time)) * 1000 as processTime, DATE_FORMAT(A.UPDATE_TIME, '%Y-%m-%d %H:%i:%s:%f3') as batchEndTime, A.TASK_STATUS as taskStatusString, A.START_MODE as startMode, A.CREATE_USER as createUser, A.BATCH_EXEDETAIL_SEQ_NO batchExedetailSeqNo FROM SYS_BATCH_EXEC_INFO A left join SYS_BATCH_TASK B on A.TASK_ID = B.TASK_ID left join SYS_BATCHGRP_EXEC_INFO D on A.BATCH_EXEDETAIL_SEQ_NO = D.SEQ_NO left join SYS_BATCH_GRP C on D.BATCH_SEQ_NO = C.SEQ_NO LEFT JOIN SYS_BATCH_PRD_GRP E ON D.PRD_GROUP_SEQ_NO = E.SEQ_NO
AND D.BATCH_SEQ_NO = #{taskGroup}
AND A.TASK_ID = #{task}
AND D.PRD_GROUP_SEQ_NO = #{prdGroup}
AND DATE_FORMAT(D.END_DATE, '%Y-%m-%d') >= #{startDate}
AND DATE_FORMAT(D.START_DATE, '%Y-%m-%d') <= #{endDate}
AND A.TASK_STATUS = #{taskStatus}
ORDER BY D.START_DATE, D.END_DATE, A.EXECUTE_DATE, A.TASK_ID, D.BATCH_SEQ_NO
